func (c *AutoGCController) RunBackgroundThread(threads *sql.BackgroundThreads, ctxF func(context.Context) (*sql.Context, error)) error {
	c.threads = threads
	c.ctxF = ctxF
	err := threads.Add("auto_gc_thread", c.gcBgThread)
	if err != nil {
		return err
	}
	for _, hook := range c.hooks {
